package com.servicerca.model; import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="media_file") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor public class MediaFile { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="owner_id") private User owner; @ManyToOne @JoinColumn(name="request_id") private ServiceRequest request; @Column(name="object_key",nullable=false,unique=true,columnDefinition="text") private String objectKey; @Column(name="content_type",length=100) private String contentType; @Column(name="size_bytes") private Long sizeBytes; @Column(name="created_at",nullable=false) private Instant createdAt; @PrePersist void pre(){if(createdAt==null)createdAt=Instant.now();} }
